descriptor.templateCss:
.ecw-root{--bg:#0f1626;--card:#141c2f;--line:#25304a;--text:#e8edf7;--muted:#93a0b8;--blue:#3b82f6;--green:#34d399;--amber:#f5b301;--red:#ef4444;--st:#64748b;--st-ink:#e2e8f0;
  width:100%;height:100%;box-sizing:border-box;background:var(--bg);color:var(--text);border-radius:12px;container-type:size;overflow:hidden;
  font-family:"Inter","Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
.ecw-root *{box-sizing:border-box}
.ecw-root [hidden]{display:none!important}
.ecw-root svg{width:1em;height:1em;flex:none}
.ecw-st-run{--st:var(--green);--st-ink:#0b1b14}
.ecw-st-stop{--st:#64748b;--st-ink:#e2e8f0}
.ecw-st-fault{--st:var(--red);--st-ink:#2b0a0a}
.ecw-st-pending{--st:var(--blue);--st-ink:#06142e}
.ecw-st-nodata{--st:var(--amber);--st-ink:#2b2100}
.ecw-body{font-size:min(1.3cqw,2.1cqh);padding:1.2em;display:flex;flex-direction:column;gap:1em;height:100%;overflow:hidden}

.ecw-header{display:flex;align-items:center;gap:1.2em}
.ecw-header-icon{width:4.2em;height:4.2em;border-radius:1em;background:var(--card);display:grid;place-items:center;flex:none;color:var(--text)}
.ecw-header-icon svg{width:2.8em;height:2.8em}
.ecw-header-text{flex:1;min-width:0}
.ecw-title{margin:0;font-size:2.1em;font-weight:700;line-height:1.15;overflow-wrap:anywhere}
.ecw-subtitle{margin:.3em 0 0;color:var(--muted);font-size:1.1em}
.ecw-badge{display:flex;align-items:center;gap:.6em;border:1.5px solid var(--amber);color:var(--amber);border-radius:999px;padding:.5em 1.1em;font-weight:600;white-space:nowrap}
.ecw-badge svg{width:1.8em;height:1.8em}

.ecw-grid{display:grid;grid-template-columns:1fr 1.2fr;gap:1.1em;flex:1;min-height:0}
.ecw-card{min-height:0;background:var(--card);border:1px solid var(--line);border-radius:1em;padding:1.3em}
.ecw-card-title{display:flex;align-items:center;gap:.7em;margin:0 0 1em;font-size:1.35em;font-weight:600}
.ecw-card-title svg{width:1.3em;height:1.3em;color:#aab6cf}
.ecw-control,.ecw-statuscard{display:flex;flex-direction:column}

.ecw-buttons{flex:1;min-height:5em;display:grid;grid-template-columns:1fr 1fr;gap:.9em}
.ecw-btn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.4em;border-radius:.9em;border:1.5px solid;font-size:1.3em;font-weight:700;cursor:pointer;font-family:inherit;transition:background .15s,color .15s}
.ecw-btn svg{width:1.9em;height:1.9em}
.ecw-on{background:rgba(52,211,153,.14);border-color:var(--green);color:var(--green)}
.ecw-on:hover:not(:disabled){background:var(--green);color:#0b1b14}
.ecw-off{background:rgba(239,68,68,.14);border-color:var(--red);color:#f87171}
.ecw-off:hover:not(:disabled){background:var(--red);color:#fff}
.ecw-btn:disabled{opacity:.35;cursor:not-allowed}
.ecw-btn:focus-visible,.ecw-seg button:focus-visible,.ecw-apply:focus-visible,.ecw-reset:focus-visible,.ecw-yes:focus-visible,.ecw-no:focus-visible{outline:2px solid #fff;outline-offset:2px}

.ecw-confirm{display:flex;align-items:center;gap:.7em;margin-top:.8em;padding:.6em .9em;border:1.5px solid var(--amber);border-radius:.7em;background:rgba(245,179,1,.1);font-size:1.05em}
.ecw-confirm-text{flex:1;min-width:0}
.ecw-yes,.ecw-no,.ecw-apply,.ecw-reset{font-family:inherit;font-size:1em;font-weight:600;border-radius:.5em;padding:.45em 1em;cursor:pointer;border:1px solid var(--line);background:#1b2540;color:var(--text)}
.ecw-yes{background:var(--amber);border-color:var(--amber);color:#2b2100}
.ecw-apply{background:var(--blue);border-color:var(--blue);color:#fff}
.ecw-reset{margin-top:.8em;border-color:var(--red);color:#f87171;background:rgba(239,68,68,.1)}
.ecw-apply:disabled,.ecw-reset:disabled{opacity:.4;cursor:not-allowed}
.ecw-msg{min-height:1.4em;margin-top:.8em;font-size:1em;color:var(--muted)}
.ecw-msg.ok{color:var(--green)}.ecw-msg.err{color:#f87171}
.ecw-divider{height:1px;background:var(--line);margin:.9em 0 1em}
.ecw-block+.ecw-block{margin-top:1em}
.ecw-label{display:block;font-size:1.1em;margin-bottom:.5em;color:var(--text)}
.ecw-seg{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line);border-radius:.7em;overflow:hidden;background:#0f1626}
.ecw-seg button{font-family:inherit;font-size:1.15em;font-weight:600;padding:.6em;border:0;background:transparent;color:var(--muted);cursor:pointer}
.ecw-seg button.active{background:var(--blue);color:#fff}
.ecw-seg button:disabled{cursor:not-allowed;opacity:.6}
.ecw-sp-row{display:flex;align-items:center;gap:.8em}
.ecw-range{flex:1;min-width:0;accent-color:var(--blue)}
.ecw-number{display:flex;align-items:center;gap:.4em;width:8.5em;border:1px solid var(--line);border-radius:.6em;background:#0f1626;padding:0 .7em}
.ecw-number:focus-within{border-color:var(--blue);box-shadow:0 0 0 2px rgba(59,130,246,.3)}
.ecw-number.ecw-invalid{border-color:var(--red)}
.ecw-sp{flex:1;min-width:0;width:100%;background:transparent;border:0;outline:0;color:var(--text);font-size:1.3em;font-weight:600;padding:.35em 0;font-family:inherit;-moz-appearance:textfield}
.ecw-sp::-webkit-outer-spin-button,.ecw-sp::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.ecw-sp-unit{color:var(--muted)}

.ecw-status{display:flex;align-items:stretch;gap:1em;flex:1;min-height:0;padding-bottom:1em;border-bottom:1px solid var(--line)}
.ecw-art{position:relative;flex:1.5;min-width:0;min-height:0;border-radius:.8em;background:radial-gradient(ellipse at 50% 65%,color-mix(in srgb,var(--st) 22%,transparent),transparent 70%)}
.ecw-root .ecw-art svg{position:absolute;inset:0;width:100%;height:100%;display:block;overflow:visible}
.ecw-status-text{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center}
.ecw-status-name{font-size:2.3em;font-weight:700;color:var(--st);line-height:1.1;overflow-wrap:anywhere}
.ecw-status-line{font-size:1.1em;color:var(--muted);margin-top:.35em}
.ecw-stats{display:flex;margin-top:auto;padding-top:1.1em}
.ecw-stat{flex:1;padding:0 1em;border-left:1px solid var(--line);display:flex;flex-direction:column;gap:.35em;min-width:0}
.ecw-stat:not([hidden]):first-of-type{border-left:0;padding-left:0}
.ecw-stat-label{color:var(--muted);font-size:1.05em}
.ecw-stat-value{font-size:1.7em;font-weight:700;overflow-wrap:anywhere}

.ecw-message{display:flex;align-items:flex-start;gap:.9em;padding:.9em 1.2em;font-size:1.1em;line-height:1.4;border-color:#2c4a82;background:rgba(59,130,246,.1)}
.ecw-message svg{width:1.5em;height:1.5em;color:var(--blue);margin-top:.05em}
.ecw-message-text{white-space:pre-line;min-width:0;overflow-wrap:anywhere}
.ecw-message.ecw-warn{border-color:#8a6a10;background:rgba(245,179,1,.1)}
.ecw-message.ecw-warn svg{color:var(--amber)}
.ecw-footer{display:flex}
.ecw-warning{flex:1;display:flex;gap:1em;align-items:flex-start;border:1.5px solid #b4413c;background:rgba(239,68,68,.1);border-radius:.9em;padding:.9em 1.2em;line-height:1.4}
.ecw-warning svg{width:2.2em;height:2.2em;color:var(--red)}
.ecw-warning-title{color:#f87171;font-weight:700;font-size:1.25em}

/* Animaciones del equipo en marcha */
.ecw-rot{transform-box:view-box;transform-origin:24px 24px}
.ecw-swing,.ecw-spin,.ecw-needle{transform-box:view-box}
.ecw-belt{stroke-dasharray:5 4}
.ecw-beltb{stroke-dasharray:10 8}
.ecw-flow{opacity:0}
.ecw-lamp{fill:var(--st);stroke:#0b1220;stroke-width:1.2}
.ecw-lamp-glow{fill:var(--st);opacity:.3;stroke:none}
.ecw-pwr{stroke:var(--st)}
.ecw-b1{transform:translateX(10px)}.ecw-b2{transform:translateX(74px)}.ecw-b3{transform:translateX(124px)}
.ecw-run .ecw-rot{animation:ecw-spin 1.1s linear infinite}
.ecw-run .ecw-spin{animation:ecw-spin 1s linear infinite}
.ecw-run .ecw-belt{animation:ecw-belt .7s linear infinite}
.ecw-run .ecw-beltb{animation:ecw-beltb .6s linear infinite}
.ecw-run .ecw-swing{animation:ecw-swing .6s ease-in-out infinite alternate}
.ecw-run .ecw-vib{animation:ecw-vib .14s linear infinite}
.ecw-run .ecw-shaftlines{animation:ecw-shaft .22s linear infinite}
.ecw-run .ecw-drum{animation:ecw-drum .25s linear infinite}
.ecw-run .ecw-wave{animation:ecw-wave 1.2s linear infinite}
.ecw-run .ecw-flow{opacity:1;animation:ecw-flow .6s linear infinite}
.ecw-run .ecw-needle{animation:ecw-needle 2.4s ease-in-out infinite alternate}
.ecw-run .ecw-box{animation:ecw-box 6s linear infinite}
.ecw-run .ecw-b2{animation-delay:-2s}.ecw-run .ecw-b3{animation-delay:-4s}
.ecw-st-pending .ecw-lamp{animation:ecw-blink 1s steps(2,jump-none) infinite}
.ecw-st-fault .ecw-lamp,.ecw-st-fault .ecw-lamp-glow{animation:ecw-blink .6s steps(2,jump-none) infinite}
@keyframes ecw-spin{to{transform:rotate(360deg)}}
@keyframes ecw-belt{to{stroke-dashoffset:-9}}
@keyframes ecw-beltb{to{stroke-dashoffset:-18}}
@keyframes ecw-swing{from{transform:scaleX(1)}to{transform:scaleX(.25)}}
@keyframes ecw-vib{0%,100%{transform:translateY(0)}50%{transform:translateY(-.7px)}}
@keyframes ecw-shaft{to{transform:translateY(6px)}}
@keyframes ecw-drum{to{transform:translateX(8px)}}
@keyframes ecw-wave{to{transform:translateX(-24px)}}
@keyframes ecw-flow{to{stroke-dashoffset:-16}}
@keyframes ecw-needle{from{transform:rotate(-12deg)}to{transform:rotate(14deg)}}
@keyframes ecw-box{0%{transform:translateX(0);opacity:0}6%{opacity:1}94%{opacity:1}100%{transform:translateX(140px);opacity:0}}
@keyframes ecw-blink{50%{opacity:.15}}
@media (prefers-reduced-motion:reduce){.ecw-run *{animation:none!important}.ecw-st-pending .ecw-lamp,.ecw-st-fault .ecw-lamp{animation:none}}

@container (max-width:620px){
  .ecw-body{font-size:min(2.6cqw,1.2cqh)}
  .ecw-grid{grid-template-columns:1fr}
  .ecw-header{flex-wrap:wrap}
}

