/* ---------- utilidades ---------- */
self.find = function (name) {
    if (!name) { return { found: false }; }
    var data = self.ctx.data || [];
    for (var i = 0; i < data.length; i++) {
        var dk = data[i].dataKey;
        if (dk && (dk.label === name || dk.name === name)) {
            var arr = data[i].data;
            var last = (arr && arr.length) ? arr[arr.length - 1] : null;
            return { found: true, value: last ? last[1] : null, ts: last ? last[0] : null, attrName: dk.name };
        }
    }
    return { found: false };
};
self.parse = function (v) {
    var t = String(v === undefined || v === null ? '' : v).trim();
    var l = t.toLowerCase();
    if (l === 'true') { return true; }
    if (l === 'false') { return false; }
    if (t !== '' && !isNaN(Number(t))) { return Number(t); }
    return t;
};
self.inList = function (v, list) {
    if (v === null || v === undefined) { return false; }
    var l = String(v).trim().toLowerCase();
    return String(list || '').toLowerCase().split(',').map(function (x) { return x.trim(); }).indexOf(l) !== -1;
};
self.toNum = function (v) {
    if (v === null || v === undefined || v === '') { return null; }
    var n = parseFloat(v);
    return isNaN(n) ? null : n;
};
self.fmtNum = function (v, unit) {
    var n = self.toNum(v);
    if (n === null) { return '—'; }
    var out = n.toLocaleString('es-PE', { maximumFractionDigits: self.S.decimals });
    return unit ? out + ' ' + unit : out;
};
self.fmtTs = function (ts) {
    if (!ts) { return ''; }
    var d = new Date(ts), n = new Date();
    return d.toDateString() === n.toDateString() ? d.toLocaleTimeString('es-PE') : d.toLocaleString('es-PE');
};
self.attrName = function (key) { return self.find(key).attrName || key; };

self.setMsg = function (text, cls, autoClear) {
    clearTimeout(self.timers.msg);
    self.msgText = text || '';
    self.msgCls = cls || '';
    if (autoClear && text) {
        self.timers.msg = setTimeout(function () { self.msgText = ''; self.msgCls = ''; self.render(); }, 6000);
    }
    self.render();
};

/* ---------- estado derivado ---------- */
self.derive = function () {
    var S = self.S;
    var st = self.find(S.stateKey);
    var running = (st.found && st.value !== null && st.value !== '') ? self.inList(st.value, S.stateOnValues) : null;
    var ft = self.find(S.faultKey);
    var fault = ft.found && self.inList(ft.value, S.faultValues);
    var md = self.find(S.modeKey);
    var mode = null;
    if (md.found && md.value !== null) {
        var mv = String(md.value).trim().toLowerCase();
        if (mv === String(S.modeAutoValue).trim().toLowerCase()) { mode = 'auto'; }
        else if (mv === String(S.modeManualValue).trim().toLowerCase()) { mode = 'manual'; }
    }
    var status = 'nodata', text = 'Sin datos';
    if (self.pending) { status = 'pending'; text = self.pending.target ? 'Arrancando…' : 'Deteniendo…'; }
    else if (fault) { status = 'fault'; text = 'Falla'; }
    else if (running === true) { status = 'run'; text = 'En marcha'; }
    else if (running === false) { status = 'stop'; text = 'Detenido'; }
    return { st: st, running: running, fault: fault, md: md, mode: mode, status: status, text: text };
};

self.onDataUpdated = function () {
    var d = self.derive();
    if (self.pending && d.running === self.pending.target) {
        clearTimeout(self.timers.pend);
        self.pending = null;
        d = self.derive();
        self.setMsg('Estado confirmado: ' + d.text + '.', 'ok', true);
        return;
    }
    self.render();
};
self.onResize = function () {};
self.onDestroy = function () {
    Object.keys(self.timers).forEach(function (k) { clearTimeout(self.timers[k]); });
};

/* ---------- render ---------- */
self.render = function () {
    var S = self.S, e = self.el, d = self.derive();
    var busy = self.saving || !!self.pending;
    var locked = S.lockInAuto === true && d.mode === 'auto';
    var blockStart = d.fault && S.blockStartOnFault !== false;

    e.root.className = 'ecw-root ecw-st-' + d.status + (d.status === 'run' ? ' ecw-run' : '');
    e.statusName.textContent = d.text;

    // Botones de marcha
    e.on.disabled = busy || locked || d.running === true || blockStart;
    e.off.disabled = busy || locked || d.running === false;
    e.confirm.hidden = !self.confirming;
    if (self.confirming) {
        e.confirmText.textContent = '¿Confirmar ' + (self.confirming === 'on' ? 'encendido' : 'apagado') + ' de ' + (S.title || self.eq.label.toLowerCase()) + '?';
    }
    e.yes.disabled = busy;
    e.reset.hidden = !(d.fault && S.resetKey);
    e.reset.disabled = busy;

    // Mensaje de retroalimentación o aviso de bloqueo
    var hint = locked ? 'Modo automático: los comandos de marcha están bloqueados.' : (blockStart ? 'Falla activa: no se puede encender hasta que se normalice.' : '');
    e.msg.textContent = self.msgText || hint;
    e.msg.className = 'ecw-msg' + (self.msgText && self.msgCls ? ' ' + self.msgCls : '');

    // Modo
    e.modeBlock.hidden = !d.md.found;
    e.mAuto.classList.toggle('active', d.mode === 'auto');
    e.mManual.classList.toggle('active', d.mode === 'manual');
    e.mAuto.disabled = e.mManual.disabled = busy;
    e.badge.textContent = d.mode === 'auto' ? 'Modo automático' : (d.mode === 'manual' ? 'Modo manual' : 'Control de equipo');
    e.lineMode.hidden = d.mode === null;
    e.lineMode.textContent = 'Modo: ' + (d.mode === 'auto' ? 'Automático' : 'Manual');

    // Consigna
    var sp = self.find(S.setpointKey);
    e.spBlock.hidden = !sp.found;
    if (sp.found) {
        var saved = self.toNum(sp.value);
        if (!self.spDirty) { self.spForm = saved; }
        e.range.min = S.setpointMin; e.range.max = S.setpointMax; e.range.step = S.setpointStep;
        e.sp.min = S.setpointMin; e.sp.max = S.setpointMax; e.sp.step = S.setpointStep;
        e.range.value = self.spForm === null ? S.setpointMin : self.spForm;
        if (document.activeElement !== e.sp) { e.sp.value = self.spForm === null ? '' : self.spForm; }
        e.spUnit.textContent = S.speedUnit || '';
        var bad = self.spDirty && !self.spValid();
        e.spNum.classList.toggle('ecw-invalid', bad);
        e.apply.disabled = busy || !self.spDirty || bad;
        e.stSp.hidden = false;
        e.vSp.textContent = self.fmtNum(saved, S.speedUnit);
    } else {
        e.stSp.hidden = true;
    }
    e.divider.hidden = e.modeBlock.hidden && e.spBlock.hidden;

    // Indicadores
    var sd = self.find(S.speedKey), hr = self.find(S.hoursKey);
    e.stSpeed.hidden = !sd.found;
    e.vSpeed.textContent = self.fmtNum(sd.value, S.speedUnit);
    e.stHours.hidden = !hr.found;
    e.vHours.textContent = self.fmtNum(hr.value, 'h');
    var ts = self.fmtTs(d.st.ts);
    e.lineTs.hidden = !ts;
    e.lineTs.textContent = 'Último cambio: ' + ts;
};

/* ---------- acciones ---------- */
self.cancelConfirm = function () {
    clearTimeout(self.timers.conf);
    self.confirming = null;
};
self.ask = function (kind) {
    if (self.S.confirmActions === false) { self.sendRun(kind === 'on'); return; }
    self.confirming = kind;
    clearTimeout(self.timers.conf);
    self.timers.conf = setTimeout(function () { self.confirming = null; self.render(); }, 6000);
    self.render();
};

self.write = function (attrs, okText, onOk) {
    var ctx = self.ctx, S = self.S;
    var ds = ctx.datasources && ctx.datasources[0];
    if (!ds || !ds.entityId || !ds.entityType) {
        self.setMsg('No hay una entidad configurada en la fuente de datos.', 'err');
        return;
    }
    self.saving = true;
    self.setMsg('Enviando…', '');
    var entityId = { entityType: ds.entityType, id: ds.entityId };
    ctx.attributeService.saveEntityAttributes(entityId, S.attributeScope || 'SHARED_SCOPE', attrs).subscribe(
        function () {
            self.saving = false;
            if (onOk) { onOk(); }
            self.setMsg(okText, okText.indexOf('Esperando') === -1 ? 'ok' : '', true);
            ctx.detectChanges && ctx.detectChanges();
        },
        function () {
            self.saving = false;
            self.setMsg('No se pudo enviar. Verifique sus permisos e intente de nuevo.', 'err');
        }
    );
};

self.sendRun = function (target) {
    var S = self.S;
    var key = self.attrName(S.commandKey || S.stateKey);
    if (!key) { self.setMsg('Configure el dato de comando en los ajustes del widget.', 'err'); return; }
    var value = self.parse(target ? S.commandOnValue : S.commandOffValue);
    var timeout = Number(S.commandTimeoutSec);
    self.write([{ key: key, value: value }],
        timeout > 0 ? 'Comando enviado. Esperando confirmación del equipo…' : 'Comando enviado.',
        function () {
            if (!(timeout > 0)) { return; }
            self.pending = { target: target };
            clearTimeout(self.timers.pend);
            self.timers.pend = setTimeout(function () {
                if (self.pending) {
                    self.pending = null;
                    self.setMsg('El equipo no confirmó el cambio de estado en ' + timeout + ' s.', 'err');
                }
            }, timeout * 1000);
        });
};

self.setMode = function (auto) {
    var S = self.S;
    var key = self.attrName(S.modeKey);
    self.write([{ key: key, value: self.parse(auto ? S.modeAutoValue : S.modeManualValue) }],
        'Modo cambiado a ' + (auto ? 'automático' : 'manual') + '.');
};

self.spValid = function () {
    var S = self.S, v = self.spForm;
    return v !== null && !isNaN(v) && v >= S.setpointMin && v <= S.setpointMax;
};
self.applySetpoint = function () {
    var S = self.S;
    if (!self.spValid()) { self.setMsg('La consigna debe estar entre ' + S.setpointMin + ' y ' + S.setpointMax + '.', 'err'); return; }
    self.write([{ key: self.attrName(S.setpointKey), value: self.spForm }], 'Consigna aplicada.', function () { self.spDirty = false; });
};

self.resetFault = function () {
    var S = self.S;
    if (!S.resetKey) { return; }
    self.write([{ key: S.resetKey, value: true }], 'Solicitud de reinicio de falla enviada.');
};

self.typeParameters = function () {
    return { maxDatasources: 1, dataKeysOptional: false };
};
